"""Complete the expanded 28-question original sarcoidosis chapter."""
from create_rheum_sarcoid_systemic import rows,q,D,T,CA,NE,ref
from qbank_authoring import finalize
PM=ref('PREDMETH randomized trial: first-line prednisone versus methotrexate','https://doi.org/10.1056/NEJMoa2501443')

q('A patient has asymptomatic stage I thoracic sarcoidosis, preserved lung function and no organ-threatening involvement. Which plan is generally reasonable?', 'Observation with an appropriate clinical and organ-monitoring plan',[
 ('High-dose systemic glucocorticoids for every radiographic node','A radiographic finding alone does not create a universal treatment indication.'),('Immediate infliximab despite no symptoms or risk','This is disproportionate without a justified treatment target.'),('No future follow-up because stage I excludes every extrapulmonary complication','Organ involvement and future changes still require appropriate surveillance.')],
 'Treat risk and burden rather than an image alone','**Some sarcoidosis can be observed without systemic immune therapy.**',['The decision depends on organ threat, symptoms, functional trajectory and patient priorities.','A favorable pulmonary presentation does not remove eye, calcium, kidney or cardiac assessment when indicated.'], '**Explain what will be monitored and which symptoms need review.**',['Reassess new dyspnea, syncope, visual or neurological symptoms promptly.','Avoid unnecessary steroid toxicity in a stable low-risk presentation.'],[['Stable low-risk disease','Observation can be appropriate'],['Organ threat','Changes the decision'],['Follow-up','Clinical and objective monitoring']],[D,T],style='clinical_scenario')

q('Which finding most strongly supports systemic disease-directed treatment in sarcoidosis?', 'Active organ-threatening disease or clinically important progressive functional impairment',[
 ('An isolated high ACE with otherwise stable assessment','A biomarker alone is not an adequate treatment target.'),('Every incidentally detected thoracic node','Some asymptomatic stable disease can be observed.'),('A historical granuloma after complete clinical resolution','Past pathology does not prove current treatment need.')],
 'Define why the patient is being treated','**Prevention of death/disability and relief of important disease burden are key goals.**',['Vision-threatening eye disease, significant cardiac or neurological involvement and progressive pulmonary disease can justify therapy.','The choice and speed depend on the threatened organ.'], '**Set measurable organ-specific goals.**',['Balance benefit against glucocorticoid and other immune-treatment toxicity.','Do not assume treatment of inflammation reverses every established scar.'],[['Organ threat','Strong treatment reason'],['Quality-of-life burden','Can also justify treatment'],['Marker alone','Insufficient']],[T])

q('A patient with pulmonary sarcoidosis needs prolonged prednisone and develops diabetes and weight gain. Which conventional steroid-sparing drug is commonly used?', 'Methotrexate',[
 ('Allopurinol','It does not treat sarcoid inflammation.'),('Colchicine as an equivalent established pulmonary disease modifier','It is not equivalent to methotrexate for this indication.'),('Hydroxychloroquine as a proven substitute for severe pulmonary disease in every case','Its selected cutaneous/metabolic roles do not establish equivalent pulmonary efficacy.')],
 'Reduce cumulative glucocorticoid harm','**Methotrexate is a commonly used steroid-sparing sarcoid treatment.**',['It has a slower onset than glucocorticoids and needs an appropriate weekly dose/folate plan.','Blood counts, liver enzymes, renal function, infection risk and pregnancy plans affect suitability.'], '**Assess response and tolerance rather than simply extend prednisone.**',['Use FVC/DLCO, symptoms and other organ outcomes.','Avoid daily dosing errors and important drug interactions.'],[['Methotrexate','Steroid-sparing option'],['Onset','Not immediate'],['Safety','Weekly dosing and laboratory monitoring']],[T,PM],style='clinical_scenario')

q('What did PREDMETH establish in previously untreated pulmonary sarcoidosis?', 'Initial methotrexate was noninferior to prednisone for change in predicted FVC at 24 weeks in the studied population',[
 ('Methotrexate was proven superior for every sarcoid organ manifestation','The study population and endpoint do not support this extrapolation.'),('Prednisone and methotrexate had identical onset and adverse-effect profiles','Different time courses and adverse effects remain clinically relevant.'),('The trial established a universal need to treat all asymptomatic stage I disease','It did not answer that indication question.')],
 'Apply a trial to its studied population and endpoint','**PREDMETH supports methotrexate as an initial option in selected pulmonary sarcoidosis.**',['It was an open-label noninferiority trial with a 24-week FVC endpoint.','The result does not replace urgent organ-specific treatment for severe cardiac, neural or ocular disease.'], '**Discuss speed of benefit, comorbidities and patient preferences.**',['Do not promise equal safety from a noninferiority efficacy result.','Continue individualized monitoring and consider the longer-term evidence limitations.'],[['Population','Previously untreated pulmonary disease'],['Endpoint','FVC change at 24 weeks'],['Limit','Not every organ or emergency']],[PM])

q('Persistent active pulmonary sarcoidosis continues despite appropriate glucocorticoid and conventional steroid-sparing treatment. Which biologic has evidence in selected refractory disease?', 'Infliximab',[
 ('Etanercept as an interchangeable TNF agent for sarcoid efficacy','TNF agents are not interchangeable for this evidence base.'),('Mepolizumab','It targets eosinophilic disease and is not an established routine refractory sarcoid agent.'),('Omalizumab','It is not an established equivalent disease-modifying sarcoid therapy.')],
 'Choose an evidence-supported refractory strategy','**Infliximab can be considered for selected persistent sarcoid inflammation.**',['First reassess whether symptoms reflect active disease, damage, infection or another cause.','TNF blockade requires TB and other infection screening.'], '**Use expert-directed benefit-risk assessment.**',['Review heart failure, demyelinating disease and other contraindications.','Measure an organ-specific response rather than treat a marker indefinitely.'],[['Infliximab','Selected refractory sarcoid option'],['Etanercept','Not equivalent evidence'],['Screening','TB and relevant infections']],[T,ref('Infliximab pulmonary sarcoid randomized trial','https://doi.org/10.1164/rccm.200603-402OC')],style='clinical_scenario')

q('Which drug can be useful in selected cutaneous sarcoidosis or calcium-metabolism manifestations, while requiring retinal-risk assessment?', 'Hydroxychloroquine',[
 ('Allopurinol','It is not the standard treatment for those sarcoid domains.'),('Propranolol','It does not provide the relevant anti-inflammatory effect.'),('Bosentan','Its pulmonary vascular role is distinct from this cutaneous/metabolic use.')],
 'Match the drug to the organ domain','**Hydroxychloroquine has a selected role in cutaneous and calcium-related sarcoid management.**',['It is not a substitute for adequate treatment of every severe pulmonary or cardiac manifestation.','Dose and retinal monitoring should follow current safety guidance.'], '**Review actual weight, kidney function and ocular risk.**',['Discuss other adverse effects and interactions.','Use objective symptom, lesion or calcium outcomes to judge benefit.'],[['Skin/calcium','Selected potential role'],['Severe organ disease','May need another regimen'],['Retina','Dose and screening matter']],[T,ref('AAO hydroxychloroquine retinal safety revision','https://www.aao.org/education/clinical-statement/revised-recommendations-on-screening-chloroquine-h')])

q('A sarcoidosis patient on glucocorticoids has low 25-hydroxyvitamin D but hypercalciuria. What is the best supplementation principle?', 'Assess calcium status and relevant vitamin D metabolites before routine high-dose supplementation, while planning bone protection individually',[
 ('Give high-dose vitamin D automatically from the low 25-OH result alone','Granulomatous calcitriol production can make this unsafe in a susceptible patient.'),('Ignore all fracture prevention because sarcoidosis never affects bone risk','Glucocorticoids and other factors can increase fracture risk.'),('Use serum ACE alone to calculate the calcium dose','ACE does not provide a supplementation dosing rule.')],
 'Bone protection and calcium dysregulation must be considered together','**A low storage vitamin D level does not exclude excess active calcitriol in sarcoidosis.**',['ATS recommends considering both 25-OH and 1,25-dihydroxy vitamin D when replacement is being evaluated.','Calcium, urine calcium, kidney function and fracture risk shape the plan.'], '**Avoid reflex high-dose replacement without the metabolic context.**',['Use specialist input when hypercalcemia/hypercalciuria complicates prevention.','Consider appropriate non-supplement bone-protection strategies as indicated.'],[['25-OH vitamin D','Storage marker'],['1,25-OH2 vitamin D','Can be high from granulomas'],['Plan','Calcium safety plus fracture prevention']],[D],style='clinical_scenario')

q('A patient with advanced fibrotic sarcoidosis has worsening breathlessness despite little evidence of active inflammation. What is the most appropriate next principle?', 'Assess irreversible damage and complications, and consider rehabilitation, oxygen or advanced-disease referral rather than reflexively escalating immune therapy',[
 ('Assume every symptom proves active granulomatous inflammation','Fibrosis, PH, infection and cardiac disease can drive symptoms.'),('Escalate prednisone until all radiographic scarring disappears','Established scar may not reverse and toxicity can accumulate.'),('Discharge because inactive inflammation means there are no treatable needs','Supportive and complication-directed care can still matter greatly.')],
 'Control inflammation without overlooking damaged-organ care','**Disease activity and permanent damage can diverge.**',['Reassess pulmonary hypertension, infection, oxygenation and cardiac contributors.','Rehabilitation and selected transplant referral can be appropriate in advanced disease.'], '**Identify a target for each treatment.**',['Avoid prolonged immune exposure without evidence of benefit.','Provide symptom, functional and psychosocial support.'],[['Active inflammation','Potential immune target'],['Fibrosis/complications','Need separate assessment'],['Advanced care','Oxygen, rehabilitation and referral when indicated']],[T,D],style='clinical_scenario')

if __name__=='__main__':finalize('Rheumatology',9,'Sarcoidosis','rheum-sarcoid',rows,28)
